#!/bin/bash
# Reproduces the measurements of docs/android-phone-setup.md on Linux:
# compile time and speed of recompiled code, TinyCC against clang/gcc.
#
# The workload is real recompiled MIPS code that needs no game: OpenBIOS
# (MIT, psxrecomp/bios/openbios.bin), generated by psxrecomp-bios. main.c calls
# its memcpy, qsort (with strcmp as the comparator, through the dispatcher),
# strtol and strlen; stubs.c stands in for the runtime (always clang -O2, as
# the runtime would be precompiled in the APK).
#
#   TCC_DIR=/path/to/tinycc  tools/android/phone_setup_bench/run.sh [reps]
#
# TCC_DIR: a built tinycc tree (./configure && make && make cross-arm64).
# Needs clang, gcc, cmake, ninja; for the arm64 part also qemu-aarch64 and
# aarch64-linux-gnu-gcc (Ubuntu: qemu-user gcc-aarch64-linux-gnu).
# Behind a proxy that blocks the libchdr download, clone libchdr and pass
# FETCHCONTENT_SOURCE_DIR_PSX_LIBCHDR=/path/to/libchdr.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../../.." && pwd)
P=$ROOT/psxrecomp
REPS=${1:-30}
T=${TCC_DIR:?set TCC_DIR to a built tinycc tree}
W=${WORK:-$(mktemp -d)}
echo "work: $W"
t() { /usr/bin/time -f "$1: %e s, %M KB max RSS" "${@:2}"; }

if [ ! -x "$P/recompiler/build/psxrecomp-bios" ]; then
    cmake -S "$P/recompiler" -B "$P/recompiler/build" -G Ninja -DCMAKE_BUILD_TYPE=Release \
        ${FETCHCONTENT_SOURCE_DIR_PSX_LIBCHDR:+-DFETCHCONTENT_SOURCE_DIR_PSX_LIBCHDR=$FETCHCONTENT_SOURCE_DIR_PSX_LIBCHDR}
    cmake --build "$P/recompiler/build" --target psxrecomp-bios
fi
mkdir -p "$P/generated"
(cd "$P" && t "psxrecomp-bios (OpenBIOS)" ./recompiler/build/psxrecomp-bios --config bios/OpenBIOS.toml >/dev/null)
FULL=$P/generated/OpenBIOS_full.c DISP=$P/generated/OpenBIOS_dispatch.c
wc -c "$FULL" "$DISP"

D="-DPSX_NATIVE_BUILD=1 -DPSX_ENABLE_BLOCK_CYCLES=1 -DPSX_NO_DEBUG_TOOLS=1 -I$P/runtime/include -I$P/generated"
TCC="$T/tcc -B$T -I$T/include -w"
cd "$W"
echo "== compile OpenBIOS_full.c"
t "gcc -O2" gcc -O2 -fPIC -w $D -c "$FULL" -o gcc.o
t "clang -O2" clang -O2 -fPIC -w $D -c "$FULL" -o clang.o
t "clang -O0" clang -O0 -fPIC -w $D -c "$FULL" -o clang0.o
t "tcc" $TCC $D -c "$FULL" -o tcc.o
t "clang -O2 --target=aarch64" clang --target=aarch64-linux-gnu -O2 -fPIC -w $D -c "$FULL" -o clang_a64.o
t "arm64-tcc" $T/arm64-tcc -B$T -I$T/include -I/usr/aarch64-linux-gnu/include -w $D -c "$FULL" -o tcc_a64.o
size gcc.o clang.o clang0.o tcc.o clang_a64.o tcc_a64.o

echo "== speed (x86-64), $REPS repetitions"
clang -O2 -w $D -c "$HERE/stubs.c" -o stubs.o
clang -O2 -w $D -c "$HERE/main.c" -o main.o
lib() {  # lib NAME COMPILER... : the generated code as libgen_NAME.so
    local name=$1; shift
    "$@" $D -shared -fPIC "$FULL" "$DISP" -o "libgen_$name.so"
}
lib clang clang -O2 -w
lib gcc gcc -O2 -w
lib clang0 clang -O0 -w
lib tcc $TCC
python3 "$HERE/tcc_flavor.py" "$P/runtime/include" inc-tcc "$FULL" full-tccflavor.c
$TCC -DPSX_NATIVE_BUILD=1 -DPSX_ENABLE_BLOCK_CYCLES=1 -DPSX_NO_DEBUG_TOOLS=1 -Iinc-tcc -I"$P/generated" \
    -shared -fPIC full-tccflavor.c "$DISP" -o libgen_tccflavor.so
for name in clang gcc clang0 tcc tccflavor; do
    cp "libgen_$name.so" libgen.so
    clang -rdynamic main.o stubs.o -L. -lgen -Wl,-rpath,"$W" -o bench
    echo -n "$name ($(stat -c %s libgen_$name.so) bytes): "; ./bench "$P/bios/openbios.bin" "$REPS"
done
echo "-- without the cycle model (PSX_ENABLE_BLOCK_CYCLES off)"
ND="-DPSX_NATIVE_BUILD=1 -DPSX_NO_DEBUG_TOOLS=1 -I$P/runtime/include -I$P/generated"
for spec in "clang:clang -O2 -w" "tcc:$TCC"; do
    name=${spec%%:*}; cmd=${spec#*:}; $cmd $ND -shared -fPIC "$FULL" "$DISP" -o libgen.so
    clang -rdynamic main.o stubs.o -L. -lgen -Wl,-rpath,"$W" -o bench
    echo -n "$name, no cycles: "; ./bench "$P/bios/openbios.bin" "$REPS"
done
echo -n "psx_interpreter.c (no timing model): "
clang -O2 -w -DPSX_NATIVE_BUILD=1 -DPSX_NO_DEBUG_TOOLS=1 -I"$P/runtime/include" \
    "$HERE/main_interp.c" "$HERE/istubs.c" "$P/runtime/src/psx_interpreter.c" stubs.o -o bench_interp
./bench_interp "$P/bios/openbios.bin" "$REPS"

if command -v qemu-aarch64 >/dev/null && command -v aarch64-linux-gnu-gcc >/dev/null; then
    echo "== speed (arm64 under qemu-user: compare the ratio, not the times)"
    export QEMU_LD_PREFIX=/usr/aarch64-linux-gnu
    CC=aarch64-linux-gnu-gcc
    $CC -O2 -w $D -c "$HERE/stubs.c" -o a64_stubs.o
    $CC -O2 -w $D -c "$HERE/main.c" -o a64_main.o
    clang --target=aarch64-linux-gnu -O2 -fPIC -w $D -c "$DISP" -o a64_disp.o
    $CC -shared clang_a64.o a64_disp.o -o liba64_clang.so
    $T/arm64-tcc -B$T -I$T/include -I/usr/aarch64-linux-gnu/include -L/usr/aarch64-linux-gnu/lib -w $D \
        -shared "$FULL" "$DISP" -o liba64_tcc.so
    for name in clang tcc; do
        cp "liba64_$name.so" liba64gen.so
        $CC -rdynamic a64_main.o a64_stubs.o -L. -la64gen -o a64_bench
        echo -n "arm64 $name: "; LD_LIBRARY_PATH="$W" qemu-aarch64 ./a64_bench "$P/bios/openbios.bin" $((REPS / 3 + 1))
    done
fi
